from typing import List

def minDeletionSize(A: List[str]) -> int:
    n = len(A)
    m = len(A[0])

    # dp[i] will store the length of the longest increasing subsequence ending at column i
    dp = [1] * m

    for i in range(1, m):
        for j in range(i):
            # Check if column j can be a part of the subsequence ending at column i
            if all(A[k][j] <= A[k][i] for k in range(n)):
                dp[i] = max(dp[i], dp[j] + 1)

    # The minimum number of columns to delete is the total number of columns minus the length of the longest increasing subsequence
    return m - max(dp)
